const items = $input.all();
const results = [];

// Replace with your trusted document source domains.
// Documents with a 'source' that is not a URL (e.g. 'internal', 'upload') are treated as trusted.
const ALLOWED_DOMAINS = ['YOUR_TRUSTED_DOMAIN_1', 'YOUR_TRUSTED_DOMAIN_2'];

// Maximum content length in characters (~50KB assuming ~4 bytes/char average).
const MAX_CONTENT_LENGTH = 12500;

// Adversarial patterns that signal a data poisoning attempt embedded in document content.
const POISON_PATTERNS = [
  { name: 'instruction_override', regex: /ignore\s+(all\s+)?(previous|prior|earlier|above)\s+(instructions?|prompts?|rules?|context)/i },
  { name: 'role_override', regex: /you\s+are\s+now\s+(a\s+|an\s+)?(?!assistant|helpful)/i },
  { name: 'system_delimiter', regex: /<\|system\|>|<<SYS>>|\[INST\]|<\|im_start\|>/i },
  { name: 'prompt_override', regex: /new\s+instructions?\s*:/i },
  { name: 'privilege_escalation', regex: /developer\s+mode|jailbreak|dan\s+mode/i },
];

for (const item of items) {
  const source = String(item.json.source || '');
  const content = String(item.json.content || '');
  const riskFlags = [];
  let valid = true;
  let rejectionReason = null;

  // Source domain validation (only for URL sources).
  let sourceDomain = null;
  try {
    const url = new URL(source);
    sourceDomain = url.hostname;
  } catch (_) {
    // Not a URL — treat as internal/trusted.
    sourceDomain = null;
  }

  if (sourceDomain !== null && !ALLOWED_DOMAINS.includes(sourceDomain)) {
    valid = false;
    rejectionReason = "Source domain '" + sourceDomain + "' is not in the trusted allowlist.";
  }

  // Content size check.
  if (valid && content.length > MAX_CONTENT_LENGTH) {
    valid = false;
    rejectionReason = 'Content length (' + content.length + ' chars) exceeds maximum (' + MAX_CONTENT_LENGTH + ' chars).';
  }

  // Adversarial content scan (data poisoning detection).
  if (valid) {
    for (const pattern of POISON_PATTERNS) {
      if (pattern.regex.test(content)) {
        riskFlags.push(pattern.name);
      }
    }
    if (riskFlags.length > 0) {
      valid = false;
      rejectionReason = 'Adversarial content patterns detected: ' + riskFlags.join(', ') + '.';
    }
  }

  results.push({
    json: {
      ...item.json,
      validation: {
        valid,
        rejection_reason: rejectionReason,
        risk_flags: riskFlags,
        content_length: content.length,
        source_domain: sourceDomain,
      },
    },
  });
}

return results;

const items = $input.all();
const results = [];

// Maximum characters to embed per document chunk.
const MAX_CHUNK_LENGTH = 8000;

for (const item of items) {
  let content = String(item.json.content || '');
  const sanitizationLog = [];
  const originalLength = content.length;

  // Strip script and style blocks first.
  const beforeScripts = content.length;
  content = content.replace(/<script[\s\S]*?<\/script>/gi, '');
  content = content.replace(/<style[\s\S]*?<\/style>/gi, '');
  if (content.length !== beforeScripts) sanitizationLog.push('stripped_scripts_styles');

  // Strip remaining HTML tags.
  const beforeHtml = content.length;
  content = content.replace(/<[^>]+>/g, ' ');
  if (content.length !== beforeHtml) sanitizationLog.push('stripped_html_tags');

  // Decode common HTML entities.
  content = content
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&nbsp;/g, ' ');

  // Remove null bytes and non-printable control characters (keep newlines and tabs).
  const beforeControl = content.length;
  content = content.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
  if (content.length !== beforeControl) sanitizationLog.push('removed_control_chars');

  // Normalize whitespace: collapse multiple spaces/tabs, limit consecutive newlines.
  content = content.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

  // Truncate to max chunk length.
  if (content.length > MAX_CHUNK_LENGTH) {
    content = content.slice(0, MAX_CHUNK_LENGTH);
    sanitizationLog.push('truncated');
  }

  results.push({
    json: {
      ...item.json,
      sanitized_content: content,
      sanitization_log: sanitizationLog,
      original_length: originalLength,
      sanitized_length: content.length,
    },
  });
}

return results;
